/*
 * SPDX-License-Identifier: Apache-2.0
 *
 * CREDIT: the test harness this is linked with is generated by the Atlas team's assembler.py
 * (emit_c_file()) from their baremetal assembly tests: tapeout-chipyard 48c3a7d11f6de3f0cecb33ae6a31c24ec26ff9d8,
 * submodule sp26-atlas-acc 2ae0bef209df, baremetal/ (authors: third_party/tapeout-chipyard/NOTICE).
 * The wrap-main approach is the one of ../../upstream/shim/atlas_upstream_shim.c (ours). We own only this file.
 *
 * Glue between the team's baremetal harness (compiled unmodified) and Zephyr:
 *  - the harness's main() ends by `return 0|1`; their crt0 (htif.ld) would write that to HTIF tohost.
 *    Zephyr calls main() from a thread, so we link with --wrap=main (CMakeLists.txt) and end the run
 *    here with chipyard_sim_exit(rc) (0 = pass), as the baremetal crt0 would.
 *  - printf(): picolibc/Zephyr console instead of htif_nano.specs. Nothing to do.
 *  - Timeout: the harness waits up to 200M register reads for CSR_DBG0; a watchdog thread bounds the
 *    wall time (Kconfig ATLAS_ISA_TIMEOUT_S), stops Atlas and reports TIMEOUT.
 *
 * Output (greppable, in addition to the harness's own "*** PASSED ***" / "*** FAILED ***"):
 *   ATLASISA <test> PASS | FAIL rc=<n> | TIMEOUT after <s> s
 */
#include <stdint.h>
#include <stdio.h>
#include <zephyr/kernel.h>
#include <chipyard/sim_exit.h>

#ifndef ATLAS_ISA_NAME
#define ATLAS_ISA_NAME "unknown"
#endif

/* Penguin's Atlas execControl register (same value as CSR_EXEC_CONTROL in the harness). */
#define ATLAS_EXEC_CONTROL_ADDR 0x00040018UL

extern int __real_main(void);

/* Cooperative priority (-1): preempts the busy-polling main thread as soon as the sleep expires. */
static void watchdog(void *a, void *b, void *c)
{
	(void)a; (void)b; (void)c;
	k_sleep(K_SECONDS(CONFIG_ATLAS_ISA_TIMEOUT_S));
	*(volatile uint32_t *)ATLAS_EXEC_CONTROL_ADDR = 0;   /* do not leave Atlas running */
	printf("ATLASISA %s TIMEOUT after %d s\n", ATLAS_ISA_NAME, CONFIG_ATLAS_ISA_TIMEOUT_S);
	chipyard_sim_exit(124);
}
K_THREAD_DEFINE(atlas_isa_wd, 1024, watchdog, NULL, NULL, NULL, -1, 0, 0);

int __wrap_main(void)
{
	printf("ATLASISA %s start\n", ATLAS_ISA_NAME);
	int rc = __real_main();

	if (rc == 0) {
		printf("ATLASISA %s PASS\n", ATLAS_ISA_NAME);
	} else {
		printf("ATLASISA %s FAIL rc=%d\n", ATLAS_ISA_NAME, rc);
	}
	chipyard_sim_exit(rc);
}
